import {ATTRIBUTION,addSourceLabels,hydrateRecord} from './record-attribution.js';
import {canonicalHash} from '@little-galaxy/shared';
/** Same-origin release assets: generated by verified replay, bound to the exact frozen manifest. */
export function publishedRecords(driver,{base=import.meta.env.BASE_URL,fetcher=fetch}={}){
 let catalogue;const observed=new Map(),pending=new Map(),sourcePages=new Map();
 async function json(path){const r=await fetcher(`${base}recorded/${path}`);if(!r.ok)return null;try{return await r.json();}catch{return null;}}
 async function published(path){
  const match=/^galaxies\/([^/]+)\/(control\/certified|certifications\/(.+))$/.exec(path);if(!match)return null;
  const [,id,kind,key]=match,g=observed.get(`galaxies/${id}`),head=observed.get(`galaxies/${id}/control/head`);
  if(!g||!head||g.status==='active'||g.writePolicy!=='frozen')return null;
  catalogue??=json('index.json').catch(()=>null);
  const record=(await catalogue)?.galaxies?.find(r=>r.id===id);
  if(!record||record.manifestHash!==await canonicalHash(g)||record.sequence!==head.sequence||record.logHash!==head.hash)return null;
  if(kind==='control/certified')return record.pointer;
  if(!record.files[key])return null;
  if(!pending.has(path))pending.set(path,json(`${encodeURIComponent(id)}/${encodeURIComponent(key)}.json`));
  const value=await pending.get(path);if(!value||await canonicalHash(value)!==record.files[key])return null;
  if(value.attribution!==ATTRIBUTION)return value;
  const labels=new Map();
  await Promise.all(value.attributionPages.map(async relative=>{
   if(!/^(logPages|genesis)\/[^/]+$/u.test(relative)||!record.sourceHashes[relative])throw new Error('Invalid attribution source');
   const sourceKey=id+'/'+relative+'/'+record.sourceHashes[relative];
   if(!sourcePages.has(sourceKey))sourcePages.set(sourceKey,driver.get(`galaxies/${id}/${relative}`).then(async doc=>{if(!doc||await canonicalHash(doc)!==record.sourceHashes[relative])throw new Error('Recorded attribution source changed');return doc;}));
   addSourceLabels(labels,relative,await sourcePages.get(sourceKey));
  }));
  return hydrateRecord(value,labels);
 }
 return {...driver,watch:driver.watch?(path,next,error)=>driver.watch(path,value=>{observed.set(path,value);next(value);},error):undefined,async get(path){
  const cached=await published(path).catch(()=>null);if(cached)return cached;
  const value=await driver.get(path);if(/^galaxies\/[^/]+(?:\/control\/head)?$/.test(path))observed.set(path,value);return value;
 }};
}
